{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://gantry.example/protocol/schemas/public-checkpoint-formats-v1.schema.json",
  "title": "Gantry canonical binary checkpoint golden instances v1",
  "description": "Publication representation of exact binary checkpoint bytes. Each fixture is decoded by the named public decoder and must re-encode byte-for-byte. Length-prefixed integers are unsigned big-endian u64 values; identities and nested byte sequences are length-prefixed; booleans and enum tags are single canonical bytes; maps and task/session collections are in their codec-defined canonical order.",
  "oneOf": [
    {
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "format": { "const": "combined-checkpoint/v4" },
        "magic": { "const": "GNTCDP04" },
        "fixture_hex": {
          "type": "string",
          "pattern": "^474e544344503034(?:[0-9a-f]{2})+$"
        }
      },
      "required": ["format", "magic", "fixture_hex"]
    },
    {
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "format": { "const": "combined-checkpoint/v5" },
        "magic": { "const": "GNTCDP05" },
        "fixture_hex": {
          "type": "string",
          "pattern": "^474e544344503035(?:[0-9a-f]{2})+$"
        }
      },
      "required": ["format", "magic", "fixture_hex"]
    },
    {
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "format": { "const": "execution-budget-checkpoint/v1" },
        "magic": { "const": "GNTBGT01" },
        "fixture_hex": {
          "type": "string",
          "pattern": "^474e544247543031(?:[0-9a-f]{2})+$"
        }
      },
      "required": ["format", "magic", "fixture_hex"]
    },
    {
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "format": { "const": "machine-checkpoint/v3" },
        "magic": { "const": "GNTMCP03" },
        "fixture_hex": {
          "type": "string",
          "pattern": "^474e544d43503033(?:[0-9a-f]{2})+$"
        }
      },
      "required": ["format", "magic", "fixture_hex"]
    },
    {
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "format": { "const": "machine-checkpoint/v4" },
        "magic": { "const": "GNTMCP04" },
        "fixture_hex": {
          "type": "string",
          "pattern": "^474e544d43503034(?:[0-9a-f]{2})+$"
        }
      },
      "required": ["format", "magic", "fixture_hex"]
    },
    {
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "format": { "const": "session-checkpoint/v1" },
        "magic": { "const": "GNTSSP01" },
        "fixture_hex": {
          "type": "string",
          "pattern": "^474e545353503031(?:[0-9a-f]{2})+$"
        }
      },
      "required": ["format", "magic", "fixture_hex"]
    }
  ]
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://gantry.example/protocol/schemas/public-journal-formats-v1.schema.json",
  "title": "Gantry public journal, event, and recovery bodies v1",
  "oneOf": [
    { "$ref": "#/$defs/cancellation" },
    { "$ref": "#/$defs/concurrent_evidence" },
    { "$ref": "#/$defs/concurrent_evidence_v5" },
    { "$ref": "#/$defs/concurrent_recovery_snapshot" },
    { "$ref": "#/$defs/event_dispatched" },
    { "$ref": "#/$defs/event_occurrence" },
    { "$ref": "#/$defs/event_settled" },
    { "$ref": "#/$defs/execution_start" },
    { "$ref": "#/$defs/execution_state" },
    { "$ref": "#/$defs/logical_evidence" },
    { "$ref": "#/$defs/recovery_snapshot" }
  ],
  "$defs": {
    "unsigned": {
      "type": "number",
      "minimum": 0,
      "maximum": 9007199254740991
    },
    "hex": {
      "type": "string",
      "pattern": "^(?:[0-9a-f]{2})*$"
    },
    "identity": {
      "type": "string",
      "pattern": "^(?:activity|delivery-attempt|dispatch|event|evidence|execution|operation|session|task):[0-9a-f]{64}$"
    },
    "activity_identity": {
      "type": "string",
      "pattern": "^activity:[0-9a-f]{64}$"
    },
    "execution_identity": {
      "type": "string",
      "pattern": "^execution:[0-9a-f]{64}$"
    },
    "task_identity": {
      "type": "string",
      "pattern": "^task:[0-9a-f]{64}$"
    },
    "operation_identity": {
      "type": "string",
      "pattern": "^operation:[0-9a-f]{64}$"
    },
    "session_identity": {
      "type": "string",
      "pattern": "^session:[0-9a-f]{64}$"
    },
    "dispatch_identity": {
      "type": "string",
      "pattern": "^dispatch:[0-9a-f]{64}$"
    },
    "event_identity": {
      "type": "string",
      "pattern": "^event:[0-9a-f]{64}$"
    },
    "attempt_identity": {
      "type": "string",
      "pattern": "^delivery-attempt:[0-9a-f]{64}$"
    },
    "evidence_identity": {
      "type": "string",
      "pattern": "^evidence:[0-9a-f]{64}$"
    },
    "nullable_string": {
      "oneOf": [
        { "type": "null" },
        { "type": "string", "minLength": 1 }
      ]
    },
    "nullable_hex": {
      "oneOf": [
        { "type": "null" },
        { "$ref": "#/$defs/hex" }
      ]
    },
    "nullable_unsigned": {
      "oneOf": [
        { "type": "null" },
        { "$ref": "#/$defs/unsigned" }
      ]
    },
    "operation": {
      "oneOf": [
        { "type": "null" },
        { "$ref": "#/$defs/operation_body" }
      ]
    },
    "operation_body": {
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "action_recovery": { "$ref": "#/$defs/nullable_string" },
        "dispatch_id": { "$ref": "#/$defs/nullable_string" },
        "operation_id": { "$ref": "#/$defs/identity" },
        "outcome": {},
        "recovery_dispatch": { "$ref": "#/$defs/unsigned" },
        "request_bytes": { "$ref": "#/$defs/nullable_hex" },
        "result_bytes": { "$ref": "#/$defs/nullable_hex" },
        "result_type": { "$ref": "#/$defs/nullable_string" },
        "retries_left": { "$ref": "#/$defs/nullable_unsigned" },
        "retry_delay_us": { "$ref": "#/$defs/nullable_unsigned" },
        "retry_errors": { "type": "array" },
        "validation_attempt": { "$ref": "#/$defs/unsigned" }
      },
      "required": [
        "action_recovery",
        "dispatch_id",
        "operation_id",
        "outcome",
        "recovery_dispatch",
        "request_bytes",
        "result_bytes",
        "result_type",
        "retries_left",
        "retry_delay_us",
        "retry_errors",
        "validation_attempt"
      ]
    },
    "action_recovery": {
      "oneOf": [
        { "type": "null" },
        { "enum": ["idempotent", "non_idempotent", "read_only"] }
      ]
    },
    "hook_outcome": {
      "oneOf": [
        {
          "type": "object",
          "additionalProperties": false,
          "properties": {
            "category": { "type": "null" },
            "kind": { "const": "completed" },
            "payload": { "$ref": "#/$defs/hex" }
          },
          "required": ["category", "kind", "payload"]
        },
        {
          "type": "object",
          "additionalProperties": false,
          "properties": {
            "category": { "type": "null" },
            "kind": { "const": "declined" },
            "payload": { "type": "string" }
          },
          "required": ["category", "kind", "payload"]
        },
        {
          "type": "object",
          "additionalProperties": false,
          "properties": {
            "category": {
              "enum": [
                "cancelled",
                "policy-denied",
                "provider-failure",
                "timeout",
                "unknown-outcome"
              ]
            },
            "kind": { "const": "failed" },
            "payload": { "type": "string" }
          },
          "required": ["category", "kind", "payload"]
        }
      ]
    },
    "retry_error": {
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "category": {
          "enum": [
            "json-duplicate-key",
            "json-syntax",
            "json-unicode",
            "resource-limit",
            "schema",
            "utf8"
          ]
        },
        "instance_location": {
          "oneOf": [{ "type": "null" }, { "type": "string" }]
        },
        "message": { "type": "string", "minLength": 1 },
        "schema_location": {
          "oneOf": [{ "type": "null" }, { "type": "string" }]
        }
      },
      "required": ["category", "instance_location", "message", "schema_location"]
    },
    "operation_body_v5_prepared": {
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "action_recovery": { "$ref": "#/$defs/action_recovery" },
        "dispatch_id": { "$ref": "#/$defs/dispatch_identity" },
        "operation_id": { "$ref": "#/$defs/operation_identity" },
        "outcome": { "type": "null" },
        "recovery_dispatch": { "$ref": "#/$defs/unsigned" },
        "request_bytes": { "$ref": "#/$defs/hex" },
        "result_bytes": { "type": "null" },
        "result_type": { "type": "null" },
        "retries_left": { "$ref": "#/$defs/nullable_unsigned" },
        "retry_delay_us": { "type": "null" },
        "retry_errors": { "type": "array", "maxItems": 0 },
        "validation_attempt": { "$ref": "#/$defs/unsigned" }
      },
      "required": [
        "action_recovery",
        "dispatch_id",
        "operation_id",
        "outcome",
        "recovery_dispatch",
        "request_bytes",
        "result_bytes",
        "result_type",
        "retries_left",
        "retry_delay_us",
        "retry_errors",
        "validation_attempt"
      ]
    },
    "operation_body_v5_outcome": {
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "action_recovery": { "$ref": "#/$defs/action_recovery" },
        "dispatch_id": { "$ref": "#/$defs/dispatch_identity" },
        "operation_id": { "$ref": "#/$defs/operation_identity" },
        "outcome": { "$ref": "#/$defs/hook_outcome" },
        "recovery_dispatch": { "$ref": "#/$defs/unsigned" },
        "request_bytes": { "$ref": "#/$defs/hex" },
        "result_bytes": { "type": "null" },
        "result_type": { "type": "null" },
        "retries_left": { "$ref": "#/$defs/nullable_unsigned" },
        "retry_delay_us": { "type": "null" },
        "retry_errors": { "type": "array", "maxItems": 0 },
        "validation_attempt": { "$ref": "#/$defs/unsigned" }
      },
      "required": [
        "action_recovery",
        "dispatch_id",
        "operation_id",
        "outcome",
        "recovery_dispatch",
        "request_bytes",
        "result_bytes",
        "result_type",
        "retries_left",
        "retry_delay_us",
        "retry_errors",
        "validation_attempt"
      ]
    },
    "operation_body_v5_retry": {
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "action_recovery": { "$ref": "#/$defs/action_recovery" },
        "dispatch_id": { "$ref": "#/$defs/dispatch_identity" },
        "operation_id": { "$ref": "#/$defs/operation_identity" },
        "outcome": { "$ref": "#/$defs/hook_outcome" },
        "recovery_dispatch": { "$ref": "#/$defs/unsigned" },
        "request_bytes": { "$ref": "#/$defs/hex" },
        "result_bytes": { "type": "null" },
        "result_type": { "type": "null" },
        "retries_left": { "$ref": "#/$defs/nullable_unsigned" },
        "retry_delay_us": { "$ref": "#/$defs/unsigned" },
        "retry_errors": {
          "type": "array",
          "minItems": 1,
          "items": { "$ref": "#/$defs/retry_error" }
        },
        "validation_attempt": { "$ref": "#/$defs/unsigned" }
      },
      "required": [
        "action_recovery",
        "dispatch_id",
        "operation_id",
        "outcome",
        "recovery_dispatch",
        "request_bytes",
        "result_bytes",
        "result_type",
        "retries_left",
        "retry_delay_us",
        "retry_errors",
        "validation_attempt"
      ]
    },
    "operation_body_v5_result": {
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "action_recovery": { "$ref": "#/$defs/action_recovery" },
        "dispatch_id": { "type": "null" },
        "operation_id": { "$ref": "#/$defs/operation_identity" },
        "outcome": { "type": "null" },
        "recovery_dispatch": { "$ref": "#/$defs/unsigned" },
        "request_bytes": { "type": "null" },
        "result_bytes": { "$ref": "#/$defs/hex" },
        "result_type": { "type": "string", "minLength": 1 },
        "retries_left": { "$ref": "#/$defs/nullable_unsigned" },
        "retry_delay_us": { "type": "null" },
        "retry_errors": { "type": "array", "maxItems": 0 },
        "validation_attempt": { "$ref": "#/$defs/unsigned" }
      },
      "required": [
        "action_recovery",
        "dispatch_id",
        "operation_id",
        "outcome",
        "recovery_dispatch",
        "request_bytes",
        "result_bytes",
        "result_type",
        "retries_left",
        "retry_delay_us",
        "retry_errors",
        "validation_attempt"
      ]
    },
    "logical_evidence": {
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "budget": { "$ref": "#/$defs/hex" },
        "checkpoint": { "$ref": "#/$defs/hex" },
        "cut": { "type": "string", "minLength": 1 },
        "execution_id": { "$ref": "#/$defs/execution_identity" },
        "format": { "const": "gantry.logical-evidence/v3" },
        "operation": { "$ref": "#/$defs/operation" },
        "sessions": { "$ref": "#/$defs/nullable_hex" },
        "task_id": { "$ref": "#/$defs/task_identity" }
      },
      "required": [
        "budget",
        "checkpoint",
        "cut",
        "execution_id",
        "format",
        "operation",
        "sessions",
        "task_id"
      ]
    },
    "concurrent_evidence": {
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "checkpoint": { "$ref": "#/$defs/hex" },
        "cut": { "type": "string", "minLength": 1 },
        "execution_id": { "$ref": "#/$defs/execution_identity" },
        "format": { "const": "gantry.concurrent-durable-evidence/v4" },
        "task_id": { "$ref": "#/$defs/task_identity" }
      },
      "required": ["checkpoint", "cut", "execution_id", "format", "task_id"]
    },
    "concurrent_ownership_member": {
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "handle_child": { "$ref": "#/$defs/task_identity" },
        "handle_name": { "type": "string", "minLength": 1 },
        "handle_owner": { "$ref": "#/$defs/task_identity" },
        "task_id": { "$ref": "#/$defs/task_identity" }
      },
      "required": ["handle_child", "handle_name", "handle_owner", "task_id"]
    },
    "concurrent_ownership": {
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "control_kind": { "enum": ["detach", "join", "joinall"] },
        "disposition": { "enum": ["detached", "joined"] },
        "members": {
          "type": "array",
          "minItems": 1,
          "items": { "$ref": "#/$defs/concurrent_ownership_member" }
        },
        "owner_task_id": { "$ref": "#/$defs/task_identity" },
        "site": {
          "type": "array",
          "minItems": 1,
          "items": { "$ref": "#/$defs/unsigned" }
        },
        "workflow": { "type": "string", "pattern": "^crate::.+$" }
      },
      "required": [
        "control_kind",
        "disposition",
        "members",
        "owner_task_id",
        "site",
        "workflow"
      ]
    },
    "concurrent_evidence_v5": {
      "oneOf": [
        {
          "type": "object",
          "additionalProperties": false,
          "properties": {
            "checkpoint": { "$ref": "#/$defs/hex" },
            "cancellation": { "type": "null" },
            "cut": { "const": "operation-prepared" },
            "execution_id": { "$ref": "#/$defs/execution_identity" },
            "format": { "const": "gantry.concurrent-durable-evidence/v5" },
            "operation": { "$ref": "#/$defs/operation_body_v5_prepared" },
            "ownership": { "type": "null" },
            "record": { "const": "operation" },
            "task_id": { "$ref": "#/$defs/task_identity" }
          },
          "required": [
            "checkpoint",
            "cancellation",
            "cut",
            "execution_id",
            "format",
            "operation",
            "ownership",
            "record",
            "task_id"
          ]
        },
        {
          "type": "object",
          "additionalProperties": false,
          "properties": {
            "checkpoint": { "$ref": "#/$defs/hex" },
            "cancellation": { "type": "null" },
            "cut": { "const": "operation-outcome" },
            "execution_id": { "$ref": "#/$defs/execution_identity" },
